import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { usePeople } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { claimsKey, useClaims } from './claims';
import type { Claim } from './claims';
import { useSelectedClaims } from './selection';
import { useOneAtATime } from '../../query/useOneAtATime';

// Moves every ticked claim to the person chosen beside the button, one after another in list order
// (people in their order, each one's claims newest first), as the signed-in user. Each goes through
// the claim's own move, so it is moved by exactly its rules (role, status, closed period, retirement)
// and audited the same; one the server refuses is left as it is and counted as refused.
export function BulkReassign() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const [selected, , clear] = useSelectedClaims();
  const [moveTo, setMoveTo] = useState('');
  const [result, setResult] = useState<{ reassigned: number; refused: number } | undefined>(undefined);
  const [busy, setBusy] = useState(false);
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  if (!user || !sheet) return null;

  const run = async () => {
    setResult(undefined);
    setBusy(true);
    const ordered = people.flatMap((p) => claims.filter((c) => c.personId === p.id && selected.has(c.id)));
    let reassigned = 0;
    let refused = 0;
    try {
      for (const c of ordered) {
        try {
          if (!moveTo) throw new Error('Choose the person to move the claims to.');
          await putJson<Claim>(
            `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/person?user=${encodeURIComponent(user)}`,
            { personId: Number(moveTo), bulk: true },
          );
          reassigned++;
        } catch {
          refused++;
        }
      }
      // A ticked claim no longer listed (gone from the sheet) cannot be moved.
      refused += selected.size - ordered.length;
      clear();
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    } finally {
      setBusy(false);
      setResult({ reassigned, refused });
    }
  };

  return (
    <p>
      <select
        data-testid="bulk-reassign-to"
        aria-label="Move selected claims to"
        value={moveTo}
        onChange={(e) => setMoveTo(e.target.value)}
      >
        <option value="">move to…</option>
        {people.map((p) => (
          <option key={p.id} value={String(p.id)}>
            {p.name}
          </option>
        ))}
      </select>{' '}
      <button type="button" data-testid="bulk-reassign" disabled={busy} onClick={() => once(run)}>
        Move selected claims
      </button>
      {result && (
        <>
          {' '}
          Moved <span data-testid="bulk-reassigned">{result.reassigned}</span>, refused{' '}
          <span data-testid="bulk-reassign-refused">{result.refused}</span>
        </>
      )}
    </p>
  );
}
import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { usePeople } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { claimsKey, settleBatchesKey, useClaims, useLastBatch } from './claims';
import type { Claim } from './claims';
import { useSelectedClaims } from './selection';
import { useOneAtATime } from '../../query/useOneAtATime';

// Settles every ticked claim, one after another in list order (people in their order, each one's
// claims newest first), as the signed-in user — all or nothing: the server first checks every one, and
// if any would be refused none is settled and every one counts as refused. Each goes through the claim's
// own settle action, so a clerk's settle above the clerk limit makes it PENDING and still counts as
// settled; afterwards the bulk settle's BATCH_SETTLED line is written. Every settle carries one token for the whole bulk settle, so the
// claims it settles share one batch number (the sheet's next, taken by the first); beside the button is the sheet's last.
export function BulkSettle() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const [selected, , clear] = useSelectedClaims();
  const [result, setResult] = useState<{ settled: number; refused: number } | undefined>(undefined);
  const [busy, setBusy] = useState(false);
  const queryClient = useQueryClient();
  const once = useOneAtATime();
  const lastBatch = useLastBatch().data?.last ?? null;

  if (!user || !sheet) return null;

  const run = async () => {
    setResult(undefined);
    setBusy(true);
    const ordered = people.flatMap((p) => claims.filter((c) => c.personId === p.id && selected.has(c.id)));
    let settled = 0;
    let refused = 0;
    const batch = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
    const asUser = `?user=${encodeURIComponent(user)}`;
    try {
      // All or nothing: a ticked claim no longer listed (gone from the sheet), or one the server would refuse to
      // settle, refuses every one and nothing is settled.
      let allowed = ordered.length === selected.size;
      if (allowed && ordered.length > 0) {
        try {
          await postJson(`${base}/settle-batches/check${asUser}`, { claimIds: ordered.map((c) => c.id), batch });
        } catch {
          allowed = false;
        }
      }
      if (!allowed) {
        refused = selected.size;
      } else {
        for (const c of ordered) {
          try {
            await postJson<Claim>(`${base}/claims/${c.id}/settle${asUser}`, { batch });
            settled++;
          } catch {
            refused++;
          }
        }
        if (settled > 0) await postJson(`${base}/settle-batches/done${asUser}`, { batch });
      }
      clear();
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: settleBatchesKey(sheet) }),
      ]);
    } finally {
      setBusy(false);
      setResult({ settled, refused });
    }
  };

  return (
    <p>
      <button type="button" data-testid="bulk-settle" disabled={busy} onClick={() => once(run)}>
        Settle selected claims
      </button>{' '}
      <span data-testid="bulk-settle-batch">{lastBatch ?? ''}</span>
      {result && (
        <>
          {' '}
          Settled <span data-testid="bulk-settled">{result.settled}</span>, refused{' '}
          <span data-testid="bulk-settle-refused">{result.refused}</span>
        </>
      )}
    </p>
  );
}
import { HomeMain } from '../../slots/defs/homeMain';
import { BulkOpen } from './BulkOpen';
import { BulkReassign } from './BulkReassign';
import { BulkSettle } from './BulkSettle';
import { ClaimedTotal } from './ClaimedTotal';

export const contributions = [
  HomeMain.fill({ order: 25, Component: BulkOpen }),
  HomeMain.fill({ order: 26, Component: BulkSettle }),
  HomeMain.fill({ order: 27, Component: BulkReassign }),
  HomeMain.fill({ order: 30, Component: ClaimedTotal }),
];
# Re-date an OPEN or PENDING claim to the body's date (yyyy-MM-dd). Only a steward re-dates a claim; any other status,
# a date after its person's retirement date, or a claim whose due-by falls inside a closed period is refused (400) and
# writes nothing. The claim keeps its due-by, so its period and number, and any figure a statement bound it to.
archived:
  class: net.officefloor.hq.app.sheet.CheckNotArchived
  next: viewer
viewer:
  class: net.officefloor.hq.app.setting.CheckNotViewer
  next: validate
validate:
  class: net.officefloor.hq.app.claim.ValidateRedateRequest
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: checkPeriod
checkPeriod:
  class: net.officefloor.hq.app.claim.CheckClaimPeriodOpen
  govern: [ transaction ]
  next: check
check:
  class: net.officefloor.hq.app.claim.CheckClaimRedate
  govern: [ transaction ]
  next: before
before:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: redate
redate:
  class: net.officefloor.hq.app.claim.RedateClaim
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimRedated
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
