      // A ticked claim no longer listed (gone from the sheet) cannot be moved.
      refused += selected.size - ordered.length;
      clear();
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    } finally {
      setBusy(false);
      setResult({ reassigned, refused });
    }
