package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Moves the claim to its new date, keeping its due-by, its number and any statement figure. Its period is the one
 * containing its due-by, so a re-date never moves it to another period (nor another period numbering sequence).
 */
public class RedateClaim {
    public void redate(@Val Claim claim, @Val Redating redating, ClaimRepository repository, Out<Claim> redated) {
        Claim moved = claim.redateTo(redating.to(), claim.number());
        repository.redate(moved);
        redated.set(moved);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Refuses (400) a re-date unless a steward re-dates an OPEN or PENDING claim to a date neither after its person's
 * retirement date (it keeps its due-by, so its period: a new date in a closed period is allowed); publishes the re-date.
 */
public class CheckClaimRedate {
    public void check(@RequestParam("user") String user, @Val Claim claim, @Val NewClaimDate newDate,
            SettingRepository settings, PersonRepository people, PeriodRepository periods, Out<Redating> redating)
            throws InvalidClaimException {
        LocalDate date = newDate.value();
        if (settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
            throw new InvalidClaimException("Only a steward can re-date a claim.");
        }
        if (!claim.status().open()) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be re-dated.");
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        if (person != null && person.retiredBefore(date)) {
            throw new InvalidClaimException(
                    person.name() + " is retired from " + person.retirementBefore(date) + ": no claim can be dated " + date + ".");
        }
        redating.set(new Redating(claim.date(), date));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the re-date's body once, publishing its new date; refuses (400) a missing or malformed date. */
public class ValidateRedateRequest {
    public void validate(@RequestBody RedateRequest request, Out<NewClaimDate> date) throws InvalidClaimException {
        String typed = request == null || request.date() == null ? "" : request.date().trim();
        if (typed.isEmpty()) {
            throw new InvalidClaimException("Type the claim's new date.");
        }
        try {
            date.set(new NewClaimDate(LocalDate.parse(typed)));
        } catch (DateTimeParseException ex) {
            throw new InvalidClaimException("Type a date as yyyy-mm-dd.");
        }
    }
}
package net.officefloor.hq.app.claim;

/** What a re-date submits: the claim's new date (yyyy-MM-dd; null or blank: none typed). */
public record RedateRequest(String date) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the claim just re-dated, with its person's name, then its old and new dates. */
public class AuditClaimRedated {
    public void audit(@Val Claim claim, @Val Redating redating, PersonRepository people,
            @RequestParam("user") String user, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record("CLAIM_REDATED sheet=" + claim.sheetId() + " by=" + user + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().setScale(2).toPlainString()
                + " date=" + claim.date() + Claim.auditNumber(claim.number()) + " old=" + redating.from() + " new="
                + redating.to());
    }
}

